.comment { border-bottom: 1px solid #ebecf0; padding: 6px 0; }
.comment .meta { font-size: 12px; color: #5e6c84; }
.progress { height: 6px; background: #dfe1e6; border-radius: 3px; overflow: hidden; }
.progress > div { height: 100%; background: #36b37e; }
svg.burndown { width: 100%; max-width: 760px; height: 260px; background: #fff; }
.loading { padding: 40px; text-align: center; color: #5e6c84; }

